/// A theme-independent paint primitive widget that renders the `mobile_spark` variable icon.
class const MyIconPaint({
  super.key,

  /// The `FILL` axis.
  final double fill = 0.0,

  /// The `GRAD` axis.
  final double grad = 0.0,

  /// The `opsz` axis.
  final double opsz = 24.0,

  /// The `ROND` axis.
  final double rond = 50.0,

  /// The `wght` axis.
  final double wght = 400.0,

  /// The icon color.
  required final Color color,
}) extends StatelessWidget {
  /// Creates a theme-independent `mobile_spark` variable icon paint primitive.
  this;

  @override
  Widget build(BuildContext context) => CustomPaint(
    painter: MyIconPainter(
      fill: fill,
      grad: grad,
      opsz: opsz,
      rond: rond,
      wght: wght,
      color: color,
    ),
    size: .infinite,
    isComplex: true,
    willChange: false,
  );
}

/// A [CustomPainter] that paints the `mobile_spark` variable icon.
@immutable
final class const MyIconPainter({
  /// The `FILL` axis.
  final double fill = 0.0,

  /// The `GRAD` axis.
  final double grad = 0.0,

  /// The `opsz` axis.
  final double opsz = 24.0,

  /// The `ROND` axis.
  final double rond = 50.0,

  /// The `wght` axis.
  final double wght = 400.0,

  /// The icon color.
  required final Color color,
}) extends CustomPainter {
  /// Creates a [CustomPainter] for the `mobile_spark` variable icon.
  this;

  @override
  void paint(Canvas canvas, Size size) {
    if (color.a <= 0.0 || size.isEmpty) return;

    final path = MyIconPath.create(
      fill: fill,
      grad: grad,
      opsz: opsz,
      rond: rond,
      wght: wght,
    );
    final paint = Paint()
      ..style = .fill
      ..color = color;

    // Apply "contain" box fit by default.
    final shortestSide = size.shortestSide;
    canvas
      ..save()
      ..translate(
        (size.width - shortestSide) / 2.0,
        (size.height - shortestSide) / 2.0,
      )
      ..scale(shortestSide, shortestSide)
      ..drawPath(path, paint)
      ..restore();
  }

  @override
  bool shouldRepaint(MyIconPainter oldDelegate) =>
      fill != oldDelegate.fill ||
      grad != oldDelegate.grad ||
      opsz != oldDelegate.opsz ||
      rond != oldDelegate.rond ||
      wght != oldDelegate.wght ||
      color != oldDelegate.color;
}

